func (this *BinanceCore) ParseTopicMarket(rawMarket any, rawTopic any) any {
	//
	//     {
	//         "marketId": 5567895,
	//         "externalId": "ext_001",
	//         "title": "UP",
	//         "question": "Will BTC go UP?",
	//         "description": "Resolves YES if BTC price increases.",
	//         "conditionId": "0xabc123",
	//         "status": "REGISTERED",
	//         "tradingStatus": "OPEN",
	//         "tradeVolume": "90000.00",
	//         "liquidity": "25000.00",
	//         "decimalPrecision": 2,
	//         "outcomes": [
	//             { "name": "YES", "price": "0.52", "chance": "0.52", "index": 0, "tokenId": "112233" }
	//         ]
	//     }
	//
	var marketId any = this.SafeString(rawMarket, "marketId")
	var topicId any = this.SafeString(rawTopic, "marketTopicId")
	var topicSlug any = this.SafeString(rawTopic, "slug")
	var vendor any = this.SafeString(rawTopic, "vendor")
	var collateral any = this.SafeString(rawTopic, "collateral", "USDT")
	var title any = this.SafeString(rawMarket, "title", marketId)
	var marketSymbol any = this.SlugToMarketSymbol(topicSlug, title)
	var tradingStatus any = this.SafeString(rawMarket, "tradingStatus")
	var status any = this.SafeString(rawMarket, "status")
	var active any = (ccxt.IsEqual(tradingStatus, "OPEN"))
	if ccxt.IsTrue(ccxt.IsEqual(tradingStatus, nil)) {
		active = ccxt.IsTrue((ccxt.IsEqual(status, "REGISTERED"))) || ccxt.IsTrue((ccxt.IsEqual(status, "OPEN")))
	}
	var resolved any = ccxt.IsTrue((ccxt.IsEqual(status, "RESOLVED"))) || ccxt.IsTrue((ccxt.IsEqual(status, "SETTLED")))
	var endDate any = this.SafeInteger(rawTopic, "endDate")
	var feeRateBps any = this.SafeString(rawTopic, "feeRateBps", "200")
	var feeRate any = this.ParseNumber(ccxt.Precise.StringDiv(feeRateBps, "10000"))
	var decimalPrecision any = this.SafeString(rawMarket, "decimalPrecision", "2")
	var pricePrecision any = this.ParseNumber(this.ParsePrecision(decimalPrecision))
	var precision any = map[string]any{
		"amount": 0.01,
		"price":  pricePrecision,
	}
	var volume any = this.SafeNumber(rawMarket, "tradeVolume")
	var liquidity any = this.SafeNumber(rawMarket, "liquidity")
	var rawOutcomes any = this.SafeList(rawMarket, "outcomes", []any{})
	var outcomes any = []any{}
	var resolvedOutcomeRaw any = nil
	var rawOutcomesLength any = ccxt.GetArrayLength(rawOutcomes)
	for oi := 0; ccxt.IsLessThan(oi, rawOutcomesLength); oi++ {
		var rawOutcome any = ccxt.GetValue(rawOutcomes, oi)
		var label any = this.SafeStringUpper(rawOutcome, "name")
		var tokenId any = this.SafeString(rawOutcome, "tokenId")
		var outcomeHandle any = ccxt.Add(ccxt.Add(marketSymbol, ":"), label)
		var price any = this.SafeString(rawOutcome, "price")
		var winnerRaw any = nil
		var settleFractionRaw any = nil
		if ccxt.IsTrue(ccxt.IsTrue(resolved) && ccxt.IsTrue((!ccxt.IsEqual(price, nil)))) {
			winnerRaw = ccxt.Precise.StringEq(price, "1")
			settleFractionRaw = ccxt.Ternary(ccxt.IsTrue((winnerRaw)), 1, 0)
			if ccxt.IsTrue(winnerRaw) {
				resolvedOutcomeRaw = outcomeHandle
			}
		}
		var winner any = winnerRaw
		var settleFraction any = settleFractionRaw
		ccxt.AppendToArray(&outcomes, map[string]any{
			"id":             tokenId,
			"outcomeId":      tokenId,
			"outcome":        outcomeHandle,
			"market":         marketSymbol,
			"label":          label,
			"price":          this.ParseNumber(price),
			"active":         active,
			"winner":         winner,
			"settleFraction": settleFraction,
			"precision":      precision,
			"info": map[string]any{
				"tokenId":       tokenId,
				"marketId":      marketId,
				"marketTopicId": topicId,
				"vendor":        vendor,
				"chainId":       this.SafeString(rawTopic, "chainId"),
				"slug":          topicSlug,
				"marketTitle":   title,
				"outcomeLabel":  label,
				"index":         this.SafeString(rawOutcome, "index"),
				"price":         price,
				"chance":        this.SafeString(rawOutcome, "chance"),
				"collateral":    collateral,
				"feeRateBps":    feeRateBps,
				"slippageBps":   this.SafeString(rawTopic, "slippageBps"),
				"conditionId":   this.SafeString(rawMarket, "conditionId"),
				"externalId":    this.SafeString(rawMarket, "externalId"),
			},
		})
	}
	var resolvedOutcome any = resolvedOutcomeRaw
	return map[string]any{
		"id":              marketId,
		"market":          marketSymbol,
		"base":            collateral,
		"quote":           collateral,
		"settle":          nil,
		"baseId":          marketId,
		"quoteId":         collateral,
		"settleId":        nil,
		"type":            "prediction",
		"marketType":      "binary",
		"executionModel":  "clob",
		"collateral":      collateral,
		"spot":            false,
		"margin":          false,
		"swap":            false,
		"future":          false,
		"option":          false,
		"prediction":      true,
		"active":          active,
		"resolved":        resolved,
		"resolvedOutcome": resolvedOutcome,
		"contract":        false,
		"linear":          nil,
		"inverse":         nil,
		"contractSize":    nil,
		"expiry":          endDate,
		"expiryDatetime":  this.Iso8601(endDate),
		"strike":          nil,
		"optionType":      nil,
		"taker":           feeRate,
		"maker":           0,
		"percentage":      true,
		"tierBased":       false,
		"feeSide":         "get",
		"precision":       precision,
		"limits": map[string]any{
			"leverage": map[string]any{
				"min": 1,
				"max": 1,
			},
			"amount": map[string]any{
				"min": nil,
				"max": nil,
			},
			"price": map[string]any{
				"min": 0.01,
				"max": 0.99,
			},
			"cost": map[string]any{
				"min": 1.5,
				"max": nil,
			},
		},
		"outcomes": outcomes,
		"info": this.Extend(rawMarket, map[string]any{
			"marketTopicId": topicId,
			"vendor":        vendor,
			"slug":          topicSlug,
			"volume":        volume,
			"liquidity":     liquidity,
		}),
		"created": this.SafeInteger(rawTopic, "publishedAt"),
	}
}

