/**
 * @method
 * @name binance#cancelOrders
 * @description cancels multiple open orders
 * @see https://developers.binance.com/en/docs/catalog/web3-wallet-prediction-trading/api/rest-api/trade#batch-cancel-orders
 * @param {string[]} ids order ids
 * @param {string} [outcome] unified outcome (required)
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @returns {object[]} a list of [prediction order structures](https://docs.ccxt.com/#/?id=prediction-order-structure)
 */
func (this *BinanceCore) CancelOrders(ids any, optionalArgs ...any) <-chan any {
	ch := make(chan any)
	go func() any {
		defer close(ch)
		defer ccxt.ReturnPanicError(ch)
		outcome := ccxt.GetArg(optionalArgs, 0, nil)
		_ = outcome
		params := ccxt.GetArg(optionalArgs, 1, map[string]any{})
		_ = params
		var outcomeObj any = nil
		if ccxt.IsTrue(!ccxt.IsEqual(outcome, nil)) {

			retRes184312 := (<-this.LoadOutcome(outcome))
			ccxt.PanicOnError(retRes184312)
			outcomeObj = this.Outcome(outcome)
		}

		wallet := (<-this.FetchWallet("cancelOrders", params))
		ccxt.PanicOnError(wallet)
		var request any = map[string]any{
			"walletAddress": ccxt.GetValue(wallet, "walletAddress"),
			"walletId":      ccxt.GetValue(wallet, "walletId"),
		}
		// flatten cancelInfoList to dot list, eg. cancelInfoList[o].orderId=1234
		for i := 0; ccxt.IsLessThan(i, ccxt.GetArrayLength(ids)); i++ {
			var key any = ccxt.Add(ccxt.Add("cancelInfoList[", this.NumberToString(i)), "].orderId")
			ccxt.AddElementToObject(request, key, ccxt.GetValue(ids, i))
		}

		response := (<-this.SapiPrivatePostTradeBatchCancel(this.Extend(request, params)))
		ccxt.PanicOnError(response)
		//
		// {
		//     "canceled": [
		//         "54124"
		//     ],
		//     "failed": [
		//         {
		//             "orderId": "54126",
		//             "reason": "ORDER_NOT_FOUND"
		//         }
		//     ]
		// }
		//
		var canceledOrders any = this.SafeList(response, "canceled", []any{})
		var outcomeSymbol any = this.SafeString(outcomeObj, "outcome", outcome)
		var failedOrders any = this.SafeList(response, "failed", []any{})
		var failedOrdersLength any = ccxt.GetArrayLength(failedOrders)
		for i := 0; ccxt.IsLessThan(i, failedOrdersLength); i++ {
			var failedOrder any = ccxt.GetValue(failedOrders, i)
			var error any = this.SafeString(failedOrder, "reason")
			panic(ccxt.OrderNotFound(ccxt.Add(ccxt.Add(ccxt.Add(ccxt.Add(this.Id, " cancelOrders() failed for "), this.SafeString(failedOrder, "orderId")), ": "), error)))
		}
		var orders any = []any{}
		var canceledOrdersLength any = ccxt.GetArrayLength(canceledOrders)
		for i := 0; ccxt.IsLessThan(i, canceledOrdersLength); i++ {
			var status any = ccxt.GetValue(canceledOrders, i)
			var order any = map[string]any{
				"id":            status,
				"clientOrderId": nil,
				"info":          status,
				"status":        "canceled",
				"outcome":       outcomeSymbol,
				"outcomeId":     this.SafeString(outcomeObj, "id"),
				"label":         this.SafeString(outcomeObj, "label"),
				"market":        this.SafeString(outcomeObj, "market"),
				"timestamp":     this.Milliseconds(),
				"datetime":      this.Iso8601(this.Milliseconds()),
			}
			ccxt.AppendToArray(&orders, this.SafePredictionOrder(order))
		}

		ch <- orders
		return nil

	}()
	return ch
}
func (this *BinanceCore) HandleErrors(code any, reason any, url any, method any, headers any, body any, response any, requestHeaders any, requestBody any) any {
	if ccxt.IsTrue(ccxt.IsEqual(response, nil)) {
		return nil
	}
	var errorCode any = this.SafeString(response, "code")
	if ccxt.IsTrue(ccxt.IsTrue((!ccxt.IsEqual(errorCode, nil))) && ccxt.IsTrue(ccxt.Precise.StringLt(errorCode, "0"))) {
		var message any = this.SafeString(response, "msg", "")
		var feedback any = ccxt.Add(ccxt.Add(this.Id, " "), body)
		this.ThrowExactlyMatchedException(ccxt.GetValue(this.Exceptions, "exact"), errorCode, feedback)
		this.ThrowBroadlyMatchedException(ccxt.GetValue(this.Exceptions, "broad"), message, feedback)
		panic(ccxt.ExchangeError(feedback))
	}
	return nil
}

/**
 * @ignore
 * @method
 * @name binance#sign
 * @description builds the request URL and attaches the standard binance SAPI HMAC-SHA256 signature — every prediction endpoint is signed
 * @param {string} path the endpoint path
 * @param {string|string[]} [api] the api group and access level
 * @param {string} [method] HTTP method
 * @param {object} [params] request parameters
 * @param {object} [headers] request headers
 * @param {object} [body] request body
 * @returns {object} a dictionary with url, method, body and headers
 */
func (this *BinanceCore) Sign(path any, optionalArgs ...any) any {
	api := ccxt.GetArg(optionalArgs, 0, "sapi")
	_ = api
	method := ccxt.GetArg(optionalArgs, 1, "GET")
	_ = method
	params := ccxt.GetArg(optionalArgs, 2, map[string]any{})
	_ = params
	headers := ccxt.GetArg(optionalArgs, 3, nil)
	_ = headers
	body := ccxt.GetArg(optionalArgs, 4, nil)
	_ = body
	var apiGroup any = ccxt.Ternary(ccxt.IsTrue(ccxt.IsString(api)), api, ccxt.GetValue(api, 0))
	var baseUrls any = ccxt.GetValue(this.Urls, "api")
	var baseUrl any = this.SafeString(baseUrls, apiGroup, ccxt.GetValue(baseUrls, "sapi"))
	var url any = ccxt.Add(ccxt.Add(baseUrl, "/"), this.ImplodeParams(path, params))
	var query any = this.Omit(params, this.ExtractParams(path))
	this.CheckRequiredCredentials()
	var extendedParams any = this.Extend(map[string]any{
		"timestamp": this.Nonce(),
	}, query)
	var defaultRecvWindow any = this.SafeInteger(this.Options, "recvWindow")
	if ccxt.IsTrue(!ccxt.IsEqual(defaultRecvWindow, nil)) {
		ccxt.AddElementToObject(extendedParams, "recvWindow", defaultRecvWindow)
	}
	var querystring any = this.UrlencodeNested(extendedParams)
	querystring = ccxt.Replace(querystring, "%5B", "[")
	querystring = ccxt.Replace(querystring, "%5D", "]")
	var signature any = this.Hmac(this.Encode(querystring), this.Encode(this.Secret), ccxt.Sha256)
	querystring = ccxt.Add(ccxt.Add(querystring, "&signature="), signature)
	headers = map[string]any{
		"X-MBX-APIKEY": this.ApiKey,
	}
	if ccxt.IsTrue(ccxt.IsTrue((ccxt.IsEqual(method, "GET"))) || ccxt.IsTrue((ccxt.IsEqual(method, "DELETE")))) {
		url = ccxt.Add(ccxt.Add(url, "?"), querystring)
	} else {
		body = querystring
		ccxt.AddElementToObject(headers, "Content-Type", "application/x-www-form-urlencoded")
	}
	return map[string]any{
		"url":     url,
		"method":  method,
		"body":    body,
		"headers": headers,
	}
}

func (this *BinanceCore) Init(userConfig map[string]any) {
	this.BaseExchange = ccxt.BaseExchange{}
	this.BaseExchange.DerivedExchange = this
	this.BaseExchange.InitParent(userConfig, this.Describe().(map[string]any), this)
}
